  "insights.preview.lifeRebuilt.body": { en: "I lost my business, fell deeply into debt and felt defeated. This is how hope, disciplined study and six months of daily practice helped me rebuild my life from the inside out.", es: "I lost my business, fell deeply into debt and felt defeated. This is how hope, disciplined study and six months of daily practice helped me rebuild my life from the inside out." },
