  "coaching.stage.foundation.outcome": { en: "Build stillness, self-awareness and a dependable mental foundation.", es: "Desarrolla quietud, autoconocimiento y una base mental sólida." },
  "coaching.stage.foundation.inclusion1": { en: "Four progressive lessons across four weeks", es: "Cuatro lecciones progresivas durante cuatro semanas" },
  "coaching.stage.foundation.inclusion2": { en: "Focused exercises and reflection prompts", es: "Ejercicios de enfoque y preguntas de reflexión" },
  "coaching.stage.foundation.inclusion3": { en: "Practical coaching support and accountability", es: "Apoyo práctico de coaching y seguimiento" },
  "coaching.foundation.format": { en: "Four progressive lessons across four weeks: One Consciousness – One Power; One Method of Finding the Truth; Thoughts Become Things; The True “Self”. Each week combines the lesson, a practical exercise, reflection and guidance from Tariq.", es: "Cuatro lecciones progresivas durante cuatro semanas: Una conciencia – un poder; Un método para encontrar la verdad; Los pensamientos se convierten en cosas; El «yo» verdadero. Cada semana combina la lección, un ejercicio práctico, reflexión y guía de Tariq." },
  "coaching.foundation.summary": { en: "Four progressive lessons across four weeks, two 45-minute Zoom coaching calls each week throughout the four-week Foundation stage — eight calls total and six hours of live Zoom coaching — plus workbook and online lesson access and WhatsApp support between calls.", es: "Cuatro lecciones progresivas durante cuatro semanas, dos llamadas de coaching por Zoom de 45 minutos cada semana durante las cuatro semanas de la etapa Fundamentos — ocho llamadas en total y seis horas de coaching en directo por Zoom — además de acceso al cuaderno y a las lecciones online y apoyo por WhatsApp entre llamadas." },
  "coaching.foundation.call": { en: "Two 45-minute Zoom coaching calls each week throughout the four-week Foundation stage: eight calls total — six hours of live Zoom coaching", es: "Dos llamadas de coaching por Zoom de 45 minutos cada semana durante las cuatro semanas de la etapa Fundamentos: ocho llamadas en total — seis horas de coaching en directo por Zoom" },
  "coaching.foundation.whatsapp": { en: "WhatsApp support between calls", es: "Apoyo por WhatsApp entre llamadas" },
  "coaching.foundation.access": { en: "Workbook and lesson access for Weeks 1–4", es: "Acceso al cuaderno y a las lecciones de las Semanas 1–4" },
  "coaching.foundation.time": { en: "Approximately 45 minutes to read the chapter and 30 minutes for the meditation exercise each day. That is approximately 21 hours of chapter reading and approximately 14 hours of meditation practice across four weeks. This includes eight 45-minute Zoom calls — six hours of live Zoom coaching — for approximately 41 hours total commitment.", es: "Aproximadamente 45 minutos para leer el capítulo y 30 minutos para el ejercicio de meditación cada día. Esto supone aproximadamente 21 horas de lectura de los capítulos y aproximadamente 14 horas de práctica de meditación durante cuatro semanas. Esto incluye ocho llamadas de coaching por Zoom de 45 minutos — seis horas de coaching en directo por Zoom — para una dedicación total de aproximadamente 41 horas." },
  "coaching.foundation.afterPayment": { en: "What happens after payment: availability and confirmation are arranged through the existing approved process, then you prepare for Week 1 with your study copy and access to the lessons and workbook. Across the four weeks, attend two 45-minute Zoom coaching calls each week — eight calls total and six hours of live Zoom coaching — and use WhatsApp support between calls.", es: "Qué ocurre después del pago: la disponibilidad y la confirmación se gestionan mediante el proceso aprobado existente; después preparas la Semana 1 con tu ejemplar de estudio y acceso a las lecciones y al cuaderno. Durante las cuatro semanas, asiste a dos llamadas de coaching por Zoom de 45 minutos cada semana — ocho llamadas en total y seis horas de coaching en directo por Zoom — y usa el apoyo por WhatsApp entre llamadas." },
  "coaching.foundation.for": { en: "Who Foundation is for: people who want personal guidance, accountability and practical support while building a dependable mental foundation.", es: "Para quién es Foundation: personas que quieren guía personal, seguimiento y apoyo práctico mientras construyen una base mental sólida." },
  "coaching.foundation.notFor": { en: "Who Foundation is not for: anyone looking for guaranteed results or a passive shortcut. Results depend on your own engagement and consistent practice.", es: "Para quién no es Foundation: personas que buscan resultados garantizados o un atajo pasivo. Los resultados dependen de tu implicación y de una práctica constante." },
  "coaching.foundation.week1": { en: "What to expect in Week 1 — One Consciousness – One Power: begin with stillness, self-awareness, a practical exercise and reflection as the first step in the progressive sequence.", es: "Qué esperar en la Semana 1 — Una conciencia – un poder: empezar con quietud, autoconocimiento, un ejercicio práctico y reflexión como primer paso de la secuencia progresiva." },
  "coaching.foundation.transition": { en: "Start with the free seven-day experience, then consider Foundation if you want a structured four-week next step with personal support.", es: "Empieza con la experiencia gratuita de siete días y considera Foundation si quieres dar el siguiente paso estructurado de cuatro semanas con apoyo personal." },
  "coaching.foundation.testimonialLabel": { en: "Published student experience", es: "Experiencia publicada de un estudiante" },
  "coaching.foundation.testimonial": { en: "When I discovered that Tariq was offering a course on The Master Key System, I was immediately interested. He is the only person I have heard describe it correctly—as a course of study, rather than simply a self-help book.", es: "Cuando descubrí que Tariq ofrecía un curso sobre The Master Key System, me interesé de inmediato. Es la única persona a la que he oído describirlo correctamente: como un curso de estudio, no simplemente como un libro de autoayuda." },
  "coaching.foundation.testimonialByline": { en: "Mark Smith · UK", es: "Mark Smith · Reino Unido" },
  "coaching.foundation.paymentRefund": { en: `How payment and refunds work: Foundation is ${pricing.foundation.en} one-time and includes four progressive lessons, two 45-minute Zoom coaching calls each week across four weeks — eight calls total and six hours of live Zoom coaching. Contact Tariq to confirm availability, payment arrangements and the applicable refund terms before payment.`, es: `Cómo funcionan el pago y los reembolsos: Fundamentos cuesta ${pricing.foundation.es} en un único pago e incluye cuatro lecciones progresivas y dos llamadas de coaching por Zoom de 45 minutos cada semana durante cuatro semanas — ocho llamadas en total y seis horas de coaching en directo por Zoom. Contacta con Tariq para confirmar la disponibilidad, el pago y las condiciones de reembolso aplicables antes de pagar.` },
  "coaching.foundation.afterPaymentLabel": { en: "What happens after payment", es: "Qué ocurre después del pago" },
