  "coaching.rate.mastery.description": { en: "A selective small-group environment for deeper discussion, peer accountability, live practice, reflection and integration of the four stages.", es: "Un entorno selectivo en grupo reducido para profundizar en el diálogo, la responsabilidad entre compañeros, la práctica en directo, la reflexión y la integración de las cuatro etapas." },
  "coaching.rate.mentoring.action": { en: "Request a Private Conversation", es: "Solicita una conversación privada" },
  "coaching.rate.mentoring.description": { en: "Personalised guidance around your specific goals, decisions, habits and obstacles, with greater discretion and direct access to Tariq.", es: "Orientación personalizada sobre tus objetivos, decisiones, hábitos y obstáculos concretos, con mayor discreción y acceso directo a Tariq." },
  "coaching.rate.alumni.action": { en: "Join the Waitlist", es: "Únete a la lista de espera" },
  "coaching.rate.alumni.description": { en: "Ongoing structure after the 24-week journey, including practice sessions, reflection prompts, community and accountability to maintain momentum.", es: "Estructura continua después del recorrido de 24 semanas, con sesiones de práctica, propuestas de reflexión, comunidad y seguimiento para mantener el impulso." },
  "coaching.rate.corporate.action": { en: "Discuss Your Team’s Needs", es: "Habla sobre las necesidades de tu equipo" },
  "coaching.rate.corporate.description": { en: "Practical workshops for leadership, focus, communication, ownership, confidence and purposeful action within teams.", es: "Talleres prácticos para desarrollar liderazgo, enfoque, comunicación, responsabilidad, confianza y acción con propósito en los equipos." },
