  "coaching.build.eyebrow": { en: "WHAT YOU CAN BUILD", es: "LO QUE PUEDES CONSTRUIR" },
  "coaching.build.title": { en: "Become the conscious creator of your life.", es: "Conviértete en el creador consciente de tu vida." },
  "coaching.build.body": { en: "This is a six-month journey into the power within you: a practical, disciplined process for becoming calmer, clearer, more focused and more deliberate in the way you think, feel, choose and act.", es: "Es un recorrido de seis meses hacia el poder que hay en ti: un proceso práctico y disciplinado para pensar, sentir, elegir y actuar con más calma, claridad, enfoque e intención." },
  "coaching.build.support": { en: "You bring the willingness. Tariq brings structure, timeless Master Key principles, weekly guidance, practical exercises, accountability and support to help you live them.", es: "Tú aportas la disposición. Tariq aporta estructura, principios atemporales del Master Key, guía semanal, ejercicios prácticos, responsabilidad y apoyo para ayudarte a vivirlos." },
  "coaching.build.quote": { en: "“The reading gives you the knowledge. The daily exercise creates the transformation.”", es: "“La lectura te da el conocimiento. El ejercicio diario crea la transformación.”" },
  "coaching.build.note": { en: "Individual outcomes depend on your circumstances, participation and consistent practice.", es: "Los resultados individuales dependen de tus circunstancias, participación y práctica constante." },
  "coaching.pricing.eyebrow": { en: "CHOOSE YOUR ROUTE", es: "ELIGE TU RECORRIDO" },
  "coaching.pricing.title": { en: "Buy a stage, or take the complete 24-week journey", es: "Compra una etapa o elige el recorrido completo de 24 semanas" },
  "coaching.pricing.body": { en: "Start with the free seven-day experience, then choose the stage that fits your next step. The complete journey keeps all four stages together at the best value.", es: "Empieza con la experiencia gratuita de siete días y después elige la etapa que encaje con tu siguiente paso. El recorrido completo mantiene las cuatro etapas juntas con el mejor valor." },
  "coaching.pricing.foundationAction": { en: `Explore Foundation — ${pricing.foundation.en}`, es: `Explora Fundamentos — ${pricing.foundation.es}` },
  "coaching.pricing.completePurchase": { en: "PAY NOW", es: "PAGAR AHORA" },
  "coaching.pricing.balance": { en: `Already paid ${pricing.foundation.en} for Foundation? Continue through the remaining 20 weeks with a ${pricing.balance.en} balance. Your total for the complete journey remains ${pricing.complete.en}.`, es: `¿Ya has pagado ${pricing.foundation.es} por Fundamentos? Continúa durante las 20 semanas restantes con un saldo de ${pricing.balance.es}. El total del recorrido completo sigue siendo ${pricing.complete.es}.` },
  "coaching.services.specialistTitle": { en: "Higher-touch and specialist offers", es: "Ofertas especializadas y de mayor acompañamiento" },
  "coaching.faq.eyebrow": { en: "A FEW PRACTICAL ANSWERS", es: "ALGUNAS RESPUESTAS PRÁCTICAS" },
  "coaching.overview.title": { en: "Four progressive stages. One complete transformation journey.", es: "Cuatro etapas progresivas. Un recorrido completo de transformación." },
  "coaching.overview.body": { en: "Begin with the foundation, then build visualisation, concentration and Integration & Mastery in the sequence designed for the 24-week practice.", es: "Empieza por los fundamentos y desarrolla después la visualización, la concentración y la integración y el dominio siguiendo la secuencia diseñada para la práctica de 24 semanas." },
  "coaching.bestValue": { en: "THE COMPLETE EXPERIENCE", es: "LA EXPERIENCIA COMPLETA" },
  "coaching.full.title": { en: "Complete 24-Week Journey", es: "Recorrido completo de 24 semanas" },
  "coaching.full.body": { en: "Follow all four stages as one progressive coaching journey, with each weekly lesson preparing you for the next.", es: "Recorre las cuatro etapas como un único proceso progresivo de coaching, en el que cada lección semanal te prepara para la siguiente." },
