  "coaching.full.discountValue": { en: "44% off full RRP", es: "44% de descuento sobre el PVP completo" },
  "coaching.faq.title": { en: "Frequently Asked Questions", es: "Preguntas frecuentes" },
  "coaching.faq.1.question": { en: "How is the coaching delivered?", es: "¿Cómo se desarrolla el coaching?" },
  "coaching.faq.1.answer": { en: "The journey combines progressive weekly study, practical exercises, reflection and guidance from Tariq. Your exact session arrangements are confirmed when you enrol.", es: "El recorrido combina estudio semanal progresivo, ejercicios prácticos, reflexión y la guía de Tariq. Los detalles de tus sesiones se confirman al inscribirte." },
  "coaching.faq.2.question": { en: "How much time should I allow?", es: "¿Cuánto tiempo debo dedicar?" },
  "coaching.faq.2.answer": { en: "Set aside consistent time each week for the lesson, its exercise and your own reflection. Tariq can help you shape a realistic rhythm.", es: "Reserva un tiempo constante cada semana para la lección, el ejercicio y tu reflexión. Tariq puede ayudarte a encontrar un ritmo realista." },
  "coaching.faq.3.question": { en: "What if I miss a week?", es: "¿Qué ocurre si pierdo una semana?" },
  "coaching.faq.3.answer": { en: "Return to the current lesson without judging yourself. The emphasis is on steady application, not rushing to catch up.", es: "Retoma la lección actual sin juzgarte. Lo importante es aplicar con constancia, no correr para recuperar el tiempo." },
  "coaching.faq.4.question": { en: "Can I work at my own pace?", es: "¿Puedo avanzar a mi ritmo?" },
  "coaching.faq.4.answer": { en: "The sequence is designed to unfold progressively. Discuss timing with Tariq before changing the weekly rhythm so you preserve that progression.", es: "La secuencia está diseñada para desarrollarse de forma progresiva. Habla con Tariq antes de cambiar el ritmo semanal para conservar esa progresión." },
  "coaching.faq.5.question": { en: "Is this programme independent?", es: "¿Es un programa independiente?" },
  "coaching.faq.5.answer": { en: "Yes. This is an independent coaching experience inspired by the Master Key System. It is not endorsed by or affiliated with Charles F. Haanel.", es: "Sí. Es una experiencia de coaching independiente inspirada en el Master Key System. No cuenta con el respaldo ni la afiliación de Charles F. Haanel." },
  "coaching.faq.6.question": { en: "How do enrolment and payment work?", es: "¿Cómo funcionan la inscripción y el pago?" },
  "coaching.faq.6.answer": { en: `Start 7 Days to Change the Way You Use Your Mind. If Foundation is the right next step, you can enrol directly for ${pricing.foundation.en} through the secure PayPal checkout on the Foundation page. Foundation includes four progressive lessons, two 45-minute Zoom coaching calls each week for four weeks — eight calls total and six hours of live Zoom coaching — plus workbook access and WhatsApp support. ${pricingNote.en} If you have questions first, contact Tariq.`, es: `Empieza 7 días para cambiar la forma en que usas tu mente. Si Fundamentos es el siguiente paso adecuado, puedes inscribirte directamente por ${pricing.foundation.es} mediante el pago seguro de PayPal en la página de Fundamentos. Fundamentos incluye cuatro lecciones progresivas, dos llamadas de coaching por Zoom de 45 minutos cada semana durante cuatro semanas — ocho llamadas en total y seis horas de coaching en directo por Zoom — además de acceso al cuaderno y apoyo por WhatsApp. ${pricingNote.es} Si tienes preguntas, contacta primero con Tariq.` },
  "coaching.faq.6.answerBeforeStart": { en: "Start 7 Days to Change the Way You Use Your Mind.", es: "Empieza 7 días para cambiar la forma en que usas tu mente." },
  "coaching.faq.6.answerStartLink": { en: "Open Start Free", es: "Abrir Empieza gratis" },
  "coaching.faq.6.answerBeforeFoundation": { en: `If Foundation is the right next step, you can enrol directly for ${pricing.foundation.en} through the secure PayPal checkout on the Foundation page.`, es: `Si Fundamentos es el siguiente paso adecuado, puedes inscribirte directamente por ${pricing.foundation.es} mediante el pago seguro de PayPal en la página de Fundamentos.` },
  "coaching.faq.6.answerFoundationLink": { en: "Open the Foundation page", es: "Abrir la página de Fundamentos" },
  "coaching.faq.6.answerBeforeContact": { en: "If you have questions first,", es: "Si tienes preguntas," },
  "coaching.faq.6.answerContactLink": { en: "contact Tariq", es: "contacta con Tariq" },
  "coaching.faq.6.answerAfterContact": { en: `. ${pricingNote.en}`, es: `. ${pricingNote.es}` },
  "coaching.faq.7.question": { en: "What is your refund policy?", es: "¿Cuál es vuestra política de reembolsos?" },
  "coaching.faq.7.answerBeforeLink": { en: "Paid programme purchases may be eligible for cancellation within 14 calendar days, subject to applicable law and whether coaching or programme materials have already started or been accessed. Please read our ", es: "Las compras de programas de pago pueden ser susceptibles de cancelación dentro de los 14 días naturales, de acuerdo con la legislación aplicable y según si el coaching o los materiales del programa ya han comenzado o se han consultado. Consulta nuestra " },
  "coaching.faq.7.answerLink": { en: "Refund Policy", es: "Política de reembolsos" },
  "coaching.faq.7.answerAfterLink": { en: " for details.", es: " para obtener más información." },
  "coaching.faq.7.answer": { en: "Paid programme purchases may be eligible for cancellation within 14 calendar days, subject to applicable law and whether coaching or programme materials have already started or been accessed. Please read our <a href=\"/refund-policy/\">Refund Policy</a> for details.", es: "Las compras de programas de pago pueden ser susceptibles de cancelación dentro de los 14 días naturales, de acuerdo con la legislación aplicable y según si el coaching o los materiales del programa ya han comenzado o se han consultado. Consulta nuestra <a href=\"/refund-policy/\">Política de reembolsos</a> para obtener más información." },
  "coaching.trust.title": { en: "Ancient principles. Modern guidance. Real transformation.", es: "Principios atemporales. Guía actual. Transformación real." },
  "coaching.trust.body": { en: "An independent coaching experience inspired by the Master Key System. Results vary and depend on your own engagement and consistent practice.", es: "Una experiencia de coaching independiente inspirada en el Master Key System. Los resultados varían y dependen de tu implicación y de una práctica constante." },
