  "phase2.contact.eyebrow": { en: "CHOOSE HOW TO CONNECT", es: "ELIGE CÓMO CONTACTAR" },
  "phase2.contact.title": { en: "Coaching, a question, or simply some clarity", es: "Coaching, una pregunta o simplemente algo de claridad" },
