  "phase2.contact.coachingAction": { en: "ENQUIRE ABOUT COACHING", es: "CONSULTAR SOBRE COACHING" },
  "phase2.contact.whatsappBody": { en: "Ideal for a short, direct message. In one or two sentences, tell Tariq what brought you here.", es: "Ideal para un mensaje breve y directo. En una o dos frases, cuéntale a Tariq qué te ha traído hasta aquí." },
  "phase2.contact.whatsappAction": { en: "OPEN WHATSAPP", es: "ABRIR WHATSAPP" },
