  "phase2.contact.questionBody": { en: "If you are not ready to discuss coaching, ask what you need to know about 7 Days to Change the Way You Use Your Mind or how the wider journey works.", es: "Si aún no estás listo para hablar de coaching, pregunta lo que necesites saber sobre 7 días para cambiar la forma en que usas tu mente o sobre cómo funciona el recorrido completo." },
  "phase2.contact.questionAction": { en: "ASK A QUESTION", es: "HACER UNA PREGUNTA" },
  "phase2.contact.prepareEyebrow": { en: "MAKE THE CONVERSATION USEFUL", es: "APROVECHA LA CONVERSACIÓN" },
