  "phase2.hub.stage2Title": { en: "Visualisation", es: "Visualización" }, "phase2.hub.stage2Weeks": { en: "Weeks 5–11", es: "Semanas 5–11" }, "phase2.hub.stage2Body": { en: "Give your imagination a clear and purposeful direction.", es: "Da a tu imaginación una dirección clara y con propósito." },
  "phase2.hub.stage3Title": { en: "Concentration", es: "Concentración" }, "phase2.hub.stage3Weeks": { en: "Weeks 12–18", es: "Semanas 12–18" }, "phase2.hub.stage3Body": { en: "Strengthen attention, discipline and follow-through.", es: "Fortalece la atención, la disciplina y la constancia." },
  "phase2.hub.stage4Title": { en: "Integration & Mastery", es: "Integración y dominio" }, "phase2.hub.stage4Weeks": { en: "Weeks 19–24", es: "Semanas 19–24" }, "phase2.hub.stage4Body": { en: "Integrate the work and carry it into how you live.", es: "Integra el trabajo y llévalo a tu forma de vivir." },
  "phase2.hub.focusEyebrow": { en: "THIS WEEK’S FOCUS", es: "ENFOQUE DE ESTA SEMANA" }, "phase2.hub.focusTitle": { en: "One Consciousness — One Power", es: "Una conciencia — un poder" }, "phase2.hub.focusBody": { en: "Begin by noticing that your attention is powerful. Read the lesson slowly, practise stillness and observe what your mind returns to.", es: "Empieza observando que tu atención es poderosa. Lee la lección despacio, practica la quietud y observa a qué vuelve tu mente." }, "phase2.hub.openWeekOne": { en: "OPEN WEEK 1", es: "ABRIR SEMANA 1" }, "phase2.hub.listenAudio": { en: "LISTEN TO THE AUDIO", es: "ESCUCHAR EL AUDIO" },
  "phase2.hub.reflectionEyebrow": { en: "PRIVATE PRACTICE", es: "PRÁCTICA PRIVADA" }, "phase2.hub.reflectionTitle": { en: "Your Reflection Room", es: "Tu sala de reflexión" }, "phase2.hub.reflectionBody": { en: "Give the lesson a place to settle. Use these prompts after studying. Your notes stay on this device for now, ready for you to revisit before coaching.", es: "Da un lugar a la lección para asentarse. Usa estas preguntas después de estudiar. Tus notas permanecen por ahora en este dispositivo, listas para revisarlas antes del coaching." }, "phase2.hub.reflectionLabel": { en: "What are you noticing this week?", es: "¿Qué estás observando esta semana?" }, "phase2.hub.reflectionPlaceholder": { en: "Write a few private notes…", es: "Escribe unas notas privadas…" }, "phase2.hub.reflectionSave": { en: "SAVE MY REFLECTION", es: "GUARDAR MI REFLEXIÓN" }, "phase2.hub.reflectionStatus": { en: "", es: "" }, "phase2.hub.reflectionPrivacy": { en: "Nothing is sent to a server. Notes are saved only on this device and browser.", es: "No se envía nada a un servidor. Las notas se guardan solo en este dispositivo y navegador." },

