  "conversion.next.heading": { en: "WHAT HAPPENS NEXT?", es: "¿QUÉ OCURRE DESPUÉS?" },
  "conversion.next.step1Title": { en: "START FREE", es: "EMPIEZA GRATIS" },
  "conversion.next.step1Body": { en: "Experience 7 Days to Change the Way You Use Your Mind through guided Master Key System study, reflection and practical exercises.", es: "Vive 7 días para cambiar la forma en que usas tu mente mediante el estudio guiado del Sistema de la Llave Maestra, la reflexión y ejercicios prácticos." },
  "conversion.next.step2Title": { en: "BUILD YOUR FOUNDATION", es: "CONSTRUYE TUS FUNDAMENTOS" },
  "conversion.next.step2Body": { en: `If the journey feels right for you, continue with Foundation for ${pricing.foundation.en}: four progressive lessons across four weeks, two 45-minute Zoom coaching calls each week — eight calls total and six hours of live Zoom coaching — plus workbook and online lesson access, WhatsApp support, approximately 45 minutes to read the chapter and 30 minutes for the meditation exercise each day, approximately 21 hours of chapter reading and approximately 14 hours of meditation practice across four weeks, and approximately 41 hours total commitment.`, es: `Si sientes que este camino es adecuado para ti, continúa con Fundamentos por ${pricing.foundation.es}: cuatro lecciones progresivas durante cuatro semanas, dos llamadas de coaching por Zoom de 45 minutos cada semana — ocho llamadas en total y seis horas de coaching en directo por Zoom — además de acceso al cuaderno y a las lecciones online, apoyo por WhatsApp, aproximadamente 45 minutos para leer el capítulo y 30 minutos para el ejercicio de meditación cada día, aproximadamente 21 horas de lectura de los capítulos y aproximadamente 14 horas de práctica de meditación durante cuatro semanas, y aproximadamente 41 horas de dedicación total.` },
  "conversion.next.step2Link": { en: `VIEW FOUNDATION DETAILS — ${pricing.foundation.en}`, es: `VER LOS DETALLES DE FUNDAMENTOS — ${pricing.foundation.es}` },
  "conversion.next.step3Title": { en: "GO DEEPER, AT YOUR PACE", es: "PROFUNDIZA, A TU RITMO" },
  "conversion.next.step3Body": { en: "Continue through Visualisation, Concentration and Integration & Mastery—or join the complete 24-week journey.", es: "Continúa con Visualización, Concentración e Integración y dominio, o únete al recorrido completo de 24 semanas." },
  "conversion.next.cta": { en: "START YOUR 7 DAYS", es: "EMPIEZA TUS 7 DÍAS" },
  "conversion.foundation.eyebrow": { en: "YOUR NEXT STEP", es: "TU SIGUIENTE PASO" },
  "conversion.foundation.heading": { en: "You completed 7 Days to Change the Way You Use Your Mind.", es: "Has completado 7 días para cambiar la forma en que usas tu mente." },
  "conversion.foundation.body": { en: `If the journey feels right, continue with Foundation for ${pricing.foundation.en}: four progressive lessons across four weeks, two 45-minute Zoom coaching calls each week — eight calls total and six hours of live Zoom coaching — plus workbook and online lesson access, WhatsApp support, approximately 45 minutes to read the chapter and 30 minutes for the meditation exercise each day, approximately 21 hours of chapter reading and approximately 14 hours of meditation practice across four weeks, and approximately 41 hours total commitment.`, es: `Si el recorrido encaja contigo, continúa con Fundamentos por ${pricing.foundation.es}: cuatro lecciones progresivas durante cuatro semanas, dos llamadas de coaching por Zoom de 45 minutos cada semana — ocho llamadas en total y seis horas de coaching en directo por Zoom — además de acceso al cuaderno y a las lecciones online, apoyo por WhatsApp, aproximadamente 45 minutos para leer el capítulo y 30 minutos para el ejercicio de meditación cada día, aproximadamente 21 horas de lectura de los capítulos y aproximadamente 14 horas de práctica de meditación durante cuatro semanas, y aproximadamente 41 horas de dedicación total.` },
